package io.scenariomesh.core;import io.scenariomesh.core.Domain.ScenarioId;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.HexFormat;public final class ScenarioIds{private ScenarioIds(){}public static ScenarioId from(String adapterId,String selector){try{MessageDigest d=MessageDigest.getInstance("SHA-256");return new ScenarioId(HexFormat.of().formatHex(d.digest((adapterId+"\n"+selector).getBytes(StandardCharsets.UTF_8))));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
